<?php
namespace App\Http\Controllers;
use App\Models\Person; use App\Models\Visit; use App\Support\Audit; use Illuminate\Http\Request;
use App\Support\SystemSettings;
class PatientController extends Controller {
 private function guard(Request $r,array $roles):void {abort_unless(in_array($r->user()->role,$roles),403);}
 private function row(Person $p):array{return array_merge($p->toArray(),['firstname'=>$p->first_name,'lastname'=>$p->last_name,'student_no'=>$p->student_number,'staff_no'=>$p->staff_number,'reg_no'=>$p->registration_number,'medical_card_no'=>$p->medical_card_number,'medical_card_status'=>$p->medical_card_number?'issued':$p->verification_status]);}
 public function index(Request $r){$this->guard($r,['admin','reception','doctor']);$q=Person::query();if($r->q)$q->where(fn($x)=>$x->where('first_name','like','%'.$r->q.'%')->orWhere('last_name','like','%'.$r->q.'%')->orWhere('student_number','like','%'.$r->q.'%')->orWhere('registration_number','like','%'.$r->q.'%'));return response()->json(['data'=>$q->latest()->get()->map(fn($p)=>$this->row($p))]);}
 public function store(Request $r){$this->guard($r,['admin','reception']);$d=$r->validate(['patient_type'=>'required|in:student,staff,dependent,other','firstname'=>'required|string','lastname'=>'required|string','contact'=>'required|string','email'=>'nullable|email']);$p=Person::create(['person_type'=>$d['patient_type'],'first_name'=>$d['firstname'],'last_name'=>$d['lastname'],'phone'=>$d['contact'],'email'=>$d['email']??null,'registration_number'=>$r->reg_no,'student_number'=>$r->student_no,'staff_number'=>$r->staff_no,'faculty'=>$r->faculty,'course'=>$r->course,'verification_status'=>'approved']);Audit::record($r,'created','person',$p->id);return response()->json(['data'=>$this->row($p)],201);}
 public function show(Request $r,Person $patient){$this->guard($r,['admin','reception','doctor']);return response()->json(['data'=>$this->row($patient)]);}
 public function update(Request $r,Person $patient){$this->guard($r,['admin','reception']);$patient->update($r->only(['first_name','last_name','phone','email','address','faculty','course']));Audit::record($r,'updated','person',$patient->id);return response()->json(['data'=>$this->row($patient->fresh())]);}
 public function visits(Request $r){$this->guard($r,['admin','reception','doctor']);$q=Visit::with('person')->when($r->date==='today',fn($x)=>$x->whereDate('created_at',today()));if($r->is('*/visits/queue'))$q->whereIn('status',['waiting','in_consultation','ready_for_review','waiting_review']);return response()->json(['data'=>$q->latest()->get()->map(fn($v)=>$this->visitRow($v))]);}
 public function visitStore(Request $r){$this->guard($r,['admin','reception']);$d=$r->validate(['person_id'=>'required|exists:persons,id']);$settings=SystemSettings::operational();$n=Visit::whereDate('created_at',today())->count()+1;abort_if($n>$settings['daily_patient_limit'],422,'The daily patient limit has been reached.');$v=Visit::create(['person_id'=>$d['person_id'],'receptionist_id'=>$r->user()->id,'visit_number'=>'V-'.now()->format('Ymd').'-'.str_pad($n,3,'0',STR_PAD_LEFT),'queue_number'=>$settings['queue_prefix'].str_pad($n,3,'0',STR_PAD_LEFT),'status'=>'waiting','temperature'=>$r->temperature,'blood_pressure'=>$r->blood_pressure,'weight'=>$r->weight,'symptoms'=>$r->symptoms]);Audit::record($r,'created','visit',$v->id);return response()->json(['data'=>$this->visitRow($v->load('person'))],201);}
 public function visitUpdate(Request $r,Visit $visit){$this->guard($r,['admin','reception','doctor']);$visit->update($r->only(['status','symptoms','diagnosis','notes','doctor_id']));Audit::record($r,'updated','visit',$visit->id);return response()->json(['data'=>$this->visitRow($visit->fresh('person'))]);}
 public function start(Request $r,Visit $visit){$this->guard($r,['admin','doctor']);abort_unless(in_array($visit->status,['waiting','ready_for_review','waiting_review']),422);$visit->update(['status'=>'in_consultation','doctor_id'=>$r->user()->id]);Audit::record($r,'started','visit',$visit->id);return response()->json(['data'=>$this->visitRow($visit->fresh('person'))]);}
 public function complete(Request $r,Visit $visit){$this->guard($r,['admin','doctor']);$d=$r->validate(['status'=>'required|in:completed,discharged','notes'=>'nullable|string']);$visit->update($d);Audit::record($r,'completed','visit',$visit->id,$d);return response()->json(['data'=>$this->visitRow($visit->fresh('person'))]);}
 public function visitDelete(Request $r,Visit $visit){$this->guard($r,['admin','reception']);$visit->update(['status'=>'cancelled']);Audit::record($r,'cancelled','visit',$visit->id);return response()->noContent();}
 public function issueCard(Request $r){$this->guard($r,['admin','reception']);$d=$r->validate(['patient_id'=>'required|exists:persons,id']);$p=Person::findOrFail($d['patient_id']);$settings=SystemSettings::operational();$p->update(['verification_status'=>'approved','medical_card_number'=>$p->medical_card_number?:sprintf('%s-%s-%05d',$settings['card_number_prefix'],now()->year,$p->id),'medical_card_issued_at'=>today(),'medical_card_expires_at'=>today()->addYears($settings['default_card_validity_years'])]);Audit::record($r,'issued','medical_card',$p->id);return response()->json(['data'=>$this->row($p->fresh())]);}
 private function visitRow(Visit $v):array{$p=$v->person;return ['id'=>$v->id,'visit_no'=>$v->visit_number,'queue_no'=>$v->queue_number,'patient_id'=>$p->id,'patient_name'=>$p->full_name,'patient_type'=>$p->person_type,'reg_no'=>$p->registration_number,'student_no'=>$p->student_number,'faculty'=>$p->faculty,'course'=>$p->course,'status'=>$v->status,'temperature'=>$v->temperature,'blood_pressure'=>$v->blood_pressure,'weight'=>$v->weight,'symptoms'=>$v->symptoms,'diagnosis'=>$v->diagnosis,'notes'=>$v->notes,'created_at'=>$v->created_at];}
}
